  if src not in rows or dst not in rows or rows[src]<amount:raise ValueError()
  db.execute('UPDATE accounts SET balance=balance-? WHERE name=?',(amount,src))
  db.execute('UPDATE accounts SET balance=balance+? WHERE name=?',(amount,dst))
 except BaseException:
  try:
   db.execute('ROLLBACK TO '+name)
   db.execute('RELEASE '+name)
  except sqlite3.Error:pass
  raise
 else:db.execute('RELEASE '+name)
