  if type(capacity)is not int or capacity<1 or isinstance(ttl,bool) or not isinstance(ttl,(int,float)) or (isinstance(ttl,float) and not math.isfinite(ttl)) or ttl<=0:raise ValueError()
  self.capacity=capacity;self.ttl=ttl;self.items=OrderedDict();self.last=None
 def expire(self,now):
  if isinstance(now,bool) or not isinstance(now,(int,float)) or (isinstance(now,float) and not math.isfinite(now)):raise ValueError('clock')
  if self.last is not None and now<self.last:raise ValueError('clock')
  self.last=now
  for key,(_,deadline)in list(self.items.items()):
   if deadline<=now:del self.items[key]
 def put(self,key,value,now):
  self.expire(now);self.items[key]=(value,Fraction(now)+Fraction(self.ttl));self.items.move_to_end(key)
  while len(self.items)>self.capacity:self.items.popitem(last=False)
 def get(self,key,now):
  self.expire(now)
  if key not in self.items:raise KeyError(key)
  self.items.move_to_end(key);return self.items[key][0]
```

