from pathlib import Path
import json,hashlib
def snapshot(root,out):
 root=Path(root).resolve();out=Path(out).resolve()
 if out==root or root in out.parents:raise ValueError('output inside source')
 files={}
 for p in sorted(root.rglob('*')):
  if p.is_symlink():raise ValueError('symlink')
  if p.is_file():
   data=p.read_bytes();files[p.relative_to(root).as_posix()]={'sha256':hashlib.sha256(data).hexdigest(),'hex':data.hex()}
 out.write_text(json.dumps({'version':1,'files':files},sort_keys=True),encoding='utf-8')
def restore(archive,dest):
 data=json.loads(Path(archive).read_text(encoding='utf-8'))
 if data.get('version')!=1:raise ValueError('version')
 dest=Path(dest)
 if dest.exists():raise ValueError('destination exists')
 validated=[]
 for name,item in data['files'].items():
  parts=name.split('/')
  if not name or any(p in ('','.','..')for p in parts)or '\\'in name or ':'in name or name.startswith('/'):raise ValueError('path')
  raw=bytes.fromhex(item['hex'])
  if hashlib.sha256(raw).hexdigest()!=item['sha256']:raise ValueError('checksum')
  validated.append((name,raw))
 dest.mkdir(parents=True)
 for name,raw in validated:
  p=dest/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(raw)
 return len(validated)
```

实现snapshot(root,out)及restore(archive,dest)。备份目录普通文件(二进制支持)为version=1 JSON，保存相对路径、SHA256及hex；拒绝符号链接与源内输出。恢复先校验全部路径/摘要/版本，再写入不存在的目标目录；拒绝越界路径、反斜杠、冒号以及已存在目标。保持原源目录，返回恢复文件数。空目录信息不要求保存。

