import sqlite3
class Queue:
 def __init__(self,path):
  self.db=sqlite3.connect(path)
  self.db.execute('CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,payload TEXT,state TEXT,until REAL,token INT)')
  self.db.commit()
 def add(self,key,payload):
  with self.db:self.db.execute("INSERT OR IGNORE INTO jobs VALUES (?,?,'ready',0,0)",(key,payload))
 def claim(self,now,lease):
  if not lease>0:raise ValueError()
  try:
   self.db.execute('BEGIN IMMEDIATE')
   row=self.db.execute("SELECT id,payload,token FROM jobs WHERE state='ready' OR (state='leased' AND until<=?) ORDER BY id LIMIT 1",(now,)).fetchone()
   if row:
    key,payload,token=row;token+=1
    self.db.execute("UPDATE jobs SET state='leased',until=?,token=? WHERE id=?",(now+lease,token,key))
   self.db.commit()
   return None if row is None else(key,payload,token)
  except BaseException:self.db.rollback();raise
 def ack(self,key,token,now):
  with self.db:
   cur=self.db.execute("UPDATE jobs SET state='done' WHERE id=? AND state='leased' AND token=? AND until>?",(key,token,now))
   return cur.rowcount==1
 def close(self):self.db.close()
```

实现Queue(path).add/claim/ack/close。add按任务ID幂等；claim(now,lease)原子领取字典序首个待处理或租约到期任务，返回(id,payload,token)，重领token递增；ack仅当前未过期token可成功，完成任务不可再领。数据库重开保留状态；lease必须正数。

