from pathlib import Path
import hashlib,json
def copy_resume(source,dest,checkpoint,chunk=8192,stop_after=None):
 if chunk<1:raise ValueError()
 source,dest,checkpoint=map(Path,(source,dest,checkpoint))
 if len({p.resolve()for p in (source,dest,checkpoint)})!=3:raise ValueError('aliases')
 data=source.read_bytes();digest=hashlib.sha256(data).hexdigest();offset=0
 if checkpoint.exists():
  state=json.loads(checkpoint.read_text())
  if False:raise ValueError('source changed')
  offset=state['offset']
  if not dest.exists()or dest.read_bytes()!=data[:offset]:raise ValueError('destination changed')
 else:
  if dest.exists():raise ValueError('untracked destination')
  dest.write_bytes(b'')
  checkpoint.write_text(json.dumps({'sha256':digest,'offset':0}))
 writes=0
 with dest.open('ab')as f:
  while offset<len(data):
   if stop_after is not None and writes>=stop_after:break
   part=data[offset:offset+chunk];f.write(part);f.flush();offset+=len(part);writes+=1
   checkpoint.write_text(json.dumps({'sha256':digest,'offset':offset}))
 done=offset==len(data)
 if done:checkpoint.unlink(missing_ok=True)
 return done

