import zipfile,io
from pathlib import Path
def package(root):
 root=Path(root);entries=[]
 for p in root.rglob('*'):
  if p.is_symlink():raise ValueError('symlink')
  if p.is_file():entries.append((p.relative_to(root).as_posix(),p.read_bytes()))
 out=io.BytesIO()
 with zipfile.ZipFile(out,'w',compression=zipfile.ZIP_STORED)as z:
  for name,data in sorted(entries):
   info=zipfile.ZipInfo(name,date_time=(1980,1,1,0,0,0));info.create_system=3;info.external_attr=0o100644<<16;info.compress_type=zipfile.ZIP_STORED
   z.writestr(info,data)
 return out.getvalue()
```

实现package(root)->ZIP bytes：递归普通文件、路径排序、固定1980时间及普通0644权限、ZIP_STORED；拒绝符号链接，文件内容与相对路径完整保留。不记录空目录；相同内容即使mtime不同也生成完全相同字节。

