import hashlib
def migrate(db,migrations):
 db.execute('CREATE TABLE IF NOT EXISTS schema_version(version INT PRIMARY KEY,checksum TEXT)');db.commit()
 versions=[v for v,sql in migrations]
 if versions!=list(range(1,len(versions)+1)):raise ValueError('sequence')
 applied=dict(db.execute('SELECT version,checksum FROM schema_version'))
 if set(applied)-set(versions):raise ValueError('missing migration')
 for version,statements in migrations:
  checksum=hashlib.sha256('\n'.join(statements).encode()).hexdigest()
  if version in applied and applied[version]!=checksum:raise ValueError('modified migration')
 for version,statements in migrations:
  if version in applied:continue
  checksum=hashlib.sha256('\n'.join(statements).encode()).hexdigest()
  try:
   db.execute('BEGIN')
   for sql in statements:db.execute(sql)
   db.execute('INSERT INTO schema_version VALUES (?,?)',(version,checksum));db.commit()
  except BaseException:db.rollback();raise
 return len(migrations)-len(applied)
```

实现migrate(db,migrations)：列表(从1连续version,SQL语句列表)。记录每版本SQL用换行拼接的SHA256；已应用内容变更或版本缺失拒绝；每个新版本独立事务，失败回滚该版本及版本记录；重复执行返回0，不关闭连接。SQL材料可信，单条语句不含事务控制。

