from concurrent.futures import ThreadPoolExecutor,wait,FIRST_COMPLETED
def execute_graph(jobs,dependencies,limit):
 if type(limit)is not int or limit<1:raise ValueError('limit')
 deps={name:set(dependencies.get(name,[]))for name in jobs}
 if set(dependencies)-set(jobs)or any(d not in jobs for ds in deps.values()for d in ds):raise ValueError('unknown dependency')
 pending=set(jobs);done=set()
 while pending:
  ready={n for n in pending if deps[n]<=done}
  if not ready:raise ValueError('cycle')
  done.update(ready);pending-=ready
 states={};results={};pending=set(jobs);running={}
 with ThreadPoolExecutor(max_workers=limit)as pool:
  while pending or running:
   changed=True
   while changed:
    changed=False
    for name in sorted(pending):
     if any(states.get(d)in ('failed','skipped')for d in deps[name]):
      states[name]='skipped';pending.remove(name);changed=True;break
   for name in sorted(pending):
    if len(running)>=limit:break
    if all(states.get(d)=='ok'for d in deps[name]):
     running[pool.submit(jobs[name])]=name;pending.remove(name)
   if not running:break
   finished,_=wait(running,return_when=FIRST_COMPLETED)
   for future in finished:
    name=running.pop(future)
    try:results[name]=future.result();states[name]='ok'
    except Exception as error:results[name]=type(error).__name__;states[name]='failed'
 return states,results
```

实现execute_graph(jobs,dependencies,limit)返回states/results。先检查未知依赖和环，校验失败不得执行任何任务；依赖成功后才运行，最多limit并发；任务异常标failed，所有后代skipped且不执行，独立分支继续；成功结果保存，失败保存异常类名。

