import subprocess,threading,time,os
def supervise(argv,timeout,max_output):
 if timeout<=0 or max_output<0:raise ValueError()
 proc=subprocess.Popen(argv,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,shell=False)
 chunks=[];size=0;overflow=threading.Event()
 def read():
  nonlocal size
  while True:
   block=os.read(proc.stdout.fileno(),1024)
   if not block:break
   room=max_output-size
   chunks.append(block[:max(room,0)]);size+=min(len(block),max(room,0))
   if len(block)>room:
    overflow.set()
    try:proc.kill()
    except OSError:pass
 thread=threading.Thread(target=read,daemon=True);thread.start();timed_out=False
 try:proc.wait(timeout=timeout)
 except subprocess.TimeoutExpired:
  timed_out=True;proc.kill();proc.wait()
 thread.join(timeout=2);proc.stdout.close()
 if thread.is_alive():raise RuntimeError('reader did not stop')
 reason='output_limit'if overflow.is_set()else'timeout'if timed_out else'exit'
 return {'reason':reason,'code':proc.returncode,'output':b''.join(chunks)}
```

实现supervise(argv,timeout,max_output)：用参数数组shell=False运行直接子进程，合并stdout/stderr；超时kill并wait，输出超限kill且保留至多max_output字节；返回reason(exit/timeout/output_limit)、code、bytes output。输入命令不会创建孙进程，测试仅启动本地Python，不改变主机服务。
读到超过额度即终止，不能等满读取缓冲或超时才停止。

