import json
from pathlib import Path
class Alerts:
 def __init__(self,high,low,consecutive=2):
  if low>=high or consecutive<1:raise ValueError()
  self.high=high;self.low=low;self.n=consecutive;self.services={}
 def observe(self,service,event_id,time,value):
  state=self.services.setdefault(service,{'last':None,'seen':[],'open':False,'up':0,'down':0})
  if event_id in state['seen']:return None
  if state['last']is not None and time<state['last']:raise ValueError('out of order')
  state['last']=time;state['seen'].append(event_id)
  if not state['open']:
   state['up']=state['up']+1 if value>=self.high else 0
   if state['up']>=self.n:state.update(open=True,up=0,down=0);return 'fire'
  else:
   state['down']=state['down']+1 if value<=self.low else 0
   if state['down']>=self.n:state.update(open=False,up=0,down=0);return 'recover'
  return None
 def save(self,path):
  Path(path).write_text(json.dumps({'high':self.high,'low':self.low,'n':self.n,'services':self.services}),encoding='utf-8')
 @classmethod
 def load(cls,path):
  data=json.loads(Path(path).read_text(encoding='utf-8'));out=cls(data['high'],data['low'],data['n']);out.services=data['services'];return out
```

实现Alerts(high,low,consecutive=2).observe(service,event_id,time,value)，每服务独立：连续n次>=high触发fire，开启后连续n次<=low触发recover，中间值重置对应计数；重复event_id忽略，非重复乱序时间ValueError。save/load保存状态，重启继续计数。训练事件有限，seen允许保留全部。

