import copy,re,json
def equal(a,b):
 if isinstance(a,bool)or isinstance(b,bool):return type(a)is type(b)and a==b
 if isinstance(a,(int,float))and isinstance(b,(int,float)):return a==b
 if type(a)is not type(b):return False
 if isinstance(a,list):return len(a)==len(b)and all(equal(x,y)for x,y in zip(a,b))
 if isinstance(a,dict):return a.keys()==b.keys()and all(equal(a[k],b[k])for k in a)
 return a==b
def patch(document,operations):
 result=copy.deepcopy(document)
 def parts(path):
  if not path.startswith('/')or re.search(r'~(?![01])',path):raise ValueError('path')
  return [s.replace('~1','/').replace('~0','~')for s in path[1:].split('/')]
 def index(key,length,insert=False):
  if insert and key=='-':return length
  if not re.fullmatch(r'0|[1-9][0-9]*',key):raise ValueError('index')
  value=int(key)
  if value>=length+(1 if insert else 0):raise ValueError('range')
  return value
 for op in operations:
  keys=parts(op['path']);parent=result
  for key in keys[:-1]:
   parent=parent[index(key,len(parent))]if isinstance(parent,list)else parent[key]
  key=keys[-1];kind=op['op']
  if kind not in ('add','replace','remove','test'):raise ValueError('operation')
  if isinstance(parent,list):key=index(key,len(parent),kind=='add')
  elif not isinstance(parent,dict):raise ValueError('parent')
  if kind=='add':
   if isinstance(parent,list):parent.insert(key,copy.deepcopy(op['value']))
   else:parent[key]=copy.deepcopy(op['value'])
  else:
   try:old=parent[key]
   except (KeyError,IndexError):raise ValueError('missing')
   if kind=='test':
    if not equal(old,op['value']):raise ValueError('test failed')
   elif kind=='remove':del parent[key]
   else:parent[key]=copy.deepcopy(op['value'])
 return result
```

实现patch(document,operations)：支持add/replace/remove/test，JSON Pointer路径支持~0/~1，非空路径操作字典/列表，列表add支持-末尾追加，其他下标规范且不能越界；缺失replace/remove或test不等拒绝。所有操作作用于深拷贝，任何失败原文档不变；不支持根路径、move/copy。
test区分JSON布尔与数字，嵌套对象同样严格；字典键顺序不影响相等。

