import asyncio
async def probes(checks,limit,timeout):
 if type(limit)is not int or limit<1 or timeout<=0:raise ValueError()
 sem=asyncio.Semaphore(limit)
 async def one(name,fn):
  async with sem:
   try:
    value=await asyncio.wait_for(fn(),timeout)
    if type(value)is not bool:raise TypeError('probe result')
    return name,{'status':'up'if value else'down','detail':None}
   except asyncio.TimeoutError:return name,{'status':'timeout','detail':None}
   except Exception as exc:return name,{'status':'error','detail':type(exc).__name__}
 tasks=[asyncio.create_task(one(n,fn))for n,fn in checks.items()]
 try:
  result=dict(await asyncio.gather(*tasks))
  return {n:result[n]for n in sorted(result)}
 except BaseException:
  for task in tasks:task.cancel()
  await asyncio.gather(*tasks,return_exceptions=True)
  raise
```

