import sqlite3
def init(db):
 db.execute('CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY,balance INT NOT NULL)')
 db.execute('CREATE TABLE IF NOT EXISTS transfers(id TEXT PRIMARY KEY,src TEXT,dst TEXT,amount INT)')
 db.commit()
def move(db,transfer_id,src,dst,amount):
 if type(amount)is not int or amount<=0 or src==dst:raise ValueError()
 try:
  db.execute('BEGIN IMMEDIATE')
  previous=db.execute('SELECT src,dst,amount FROM transfers WHERE id=?',(transfer_id,)).fetchone()
  if previous:
   if previous!=(src,dst,amount):raise ValueError('id conflict')
   db.commit();return False
  balances=dict(db.execute('SELECT id,balance FROM accounts WHERE id IN (?,?)',(src,dst)))
  if src not in balances or dst not in balances or balances[src]<amount:raise ValueError('funds')
  db.execute('UPDATE accounts SET balance=balance-? WHERE id=?',(amount,src))
  db.execute('UPDATE accounts SET balance=balance+? WHERE id=?',(amount,dst))
  db.execute('INSERT INTO transfers VALUES (?,?,?,?)',(transfer_id,src,dst,amount));db.commit();return True
 except BaseException:db.rollback();raise
def verify(db):
 return {'total':db.execute('SELECT COALESCE(SUM(balance),0) FROM accounts').fetchone()[0],'transactions':db.execute('SELECT COUNT(*) FROM transfers').fetchone()[0]}
```

