from pathlib import Path
import json,copy
def load_bundle(root,entry):
 root=Path(root).resolve();active=set();cache={}
 def load(name):
  path=(root/name).resolve()
  try:path.relative_to(root)
  except ValueError:raise ValueError('outside root')
  if path in active:raise ValueError('include cycle')
  if path in cache:return copy.deepcopy(cache[path])
  active.add(path)
  try:
   obj=json.loads(path.read_text(encoding='utf-8'))
   if set(obj)!={'include','values'}or not isinstance(obj['include'],list)or not isinstance(obj['values'],dict):raise ValueError('schema')
   result={}
   for child in obj['include']:
    if not isinstance(child,str)or Path(child).is_absolute():raise ValueError('include')
    relative=(path.parent/child).relative_to(root)
    result.update(load(relative))
   result.update(obj['values']);cache[path]=copy.deepcopy(result);return result
  finally:active.remove(path)
 return load(entry)
```

实现load_bundle(root,entry)：每个JSON文件严格含include列表、values对象；include路径相对当前文件，按顺序覆盖，最后本文件values覆盖；路径解析后必须在root内；检测循环包含，缓存结果但不得污染被引用配置；返回合并对象，文件错误原样传播。

